function showResult(i){document.querySelectorAll('[data-result]').forEach(b=>{const active=+b.dataset.result===i;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});const p=document.querySelector('#result-panel');p.setAttribute('aria-labelledby',`result-tab-${i}`);p.innerHTML=`<div class="table-wrap"><table class="results-table"><thead><tr><th>Trận/Phần thi</th><th>Đội/VĐV</th><th>Kết quả</th></tr></thead><tbody><tr><td colspan="3" class="empty"><span aria-hidden="true">${sports[i].icon}</span><strong>Chưa có kết quả ${i===3?'AOE':i===4?'Bóng đá Nam':sports[i].sport}</strong><p>Kết quả sẽ được cập nhật sau khi thi đấu.</p></td></tr></tbody></table></div>`}showResult(0);
document.querySelectorAll('[data-result]').forEach(b=>{b.onclick=()=>showResult(+b.dataset.result);b.onkeydown=e=>{let i=+b.dataset.result;if(e.key==='ArrowRight')i=(i+1)%5;else if(e.key==='ArrowLeft')i=(i+4)%5;else if(e.key==='Home')i=0;else if(e.key==='End')i=4;else return;e.preventDefault();showResult(i);document.querySelector(`[data-result="${i}"]`).focus()}});
