const dialog=document.querySelector('#sport-dialog');let lastButton;document.querySelectorAll('[data-sport]').forEach(b=>b.onclick=()=>{lastButton=b;const s=sports[+b.dataset.sport];document.querySelector('#sport-detail').innerHTML=`<h2 id="dialog-title">${s.name} – ${s.sport}</h2><div class="detail-list"><section><h3>Thể thức</h3><p>Chờ cập nhật thể thức thi đấu.</p></section><section><h3>Lịch thi đấu</h3><p><strong>18/09/2026 · ${s.time}</strong></p><p>Lịch chi tiết từng trận/phần thi chờ cập nhật.</p></section><section><h3>Danh sách vận động viên/đội</h3><p>Chờ cập nhật danh sách.</p></section><section><h3>Luật thi đấu</h3><p>Chờ bổ sung luật thi đấu.</p></section><section><h3>Kết quả</h3><p>Chưa có kết quả thi đấu.</p></section></div>`;dialog.showModal();document.body.style.overflow='hidden'});document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';lastButton?.focus()});
const menuToggle=document.querySelector('.menu-toggle'),mainNav=document.querySelector('#main-nav');function closeMenu(){menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Mở menu');mainNav.classList.remove('is-open')}menuToggle.onclick=()=>{const open=menuToggle.getAttribute('aria-expanded')!=='true';menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Đóng menu':'Mở menu');mainNav.classList.toggle('is-open',open)};mainNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mainNav.classList.contains('is-open')){closeMenu();menuToggle.focus()}});matchMedia('(min-width:1001px)').addEventListener('change',closeMenu);

