const ruleSummaries={
 tug:{title:'Kéo co',key:'Luat_keo_co_Hoi_thao_Bateco_2026',quick:[['Thành phần thi đấu','Mỗi Liên minh 01 đội: 10 VĐV gồm 05 nam, 05 nữ.'],['Thể thức chính','03 Liên minh vòng tròn một lượt; mỗi đội 02 trận, mỗi trận 01 hiệp quyết định, không giới hạn thời gian.'],['Cách tính thắng / xếp hạng','Kéo dấu mốc quy định trên dây đối phương qua vạch trung tâm để thắng. Thắng 01 điểm, thua 0. Nếu cả ba đội bằng điểm: xét thời gian thắng ngắn hơn; hai đội bằng thời gian: xét đối đầu.']],notes:['Không thay người trong trận; đội hình luôn đủ 05 nam và 05 nữ.','Không quấn hoặc khóa dây vào cơ thể; không buông dây đột ngột.','Có tác động ngoại lực ngoài 10 VĐV đăng ký nhằm hỗ trợ kéo: xử thua trực tiếp.']},
 men:{title:'Nam 1.500m',key:'Luat_dien_kinh_nam_1500m_Bateco_2026',quick:[['Thành phần thi đấu','VĐV nam có tên trong danh sách đăng ký của Liên minh.'],['Thể thức chính','03 vòng sân, khoảng 1.500m; tất cả VĐV chạy cùng một lượt, xuất phát đồng thời tại vị trí được bố trí.'],['Cách tính thắng / xếp hạng','Hoàn thành hợp lệ đủ 03 vòng và về đích trước xếp trên. Nhất, Nhì, Ba nhận HCV, HCB, HCĐ; tính vào tổng sắp Liên minh.']],notes:['Xuất phát đúng vị trí và sau hiệu lệnh Trọng tài.','Không cắt ngang sân, bỏ vòng, xô đẩy hoặc cản trở VĐV khác.','Không nhận hỗ trợ kéo, đẩy hoặc dìu chạy từ người khác.']},
 women:{title:'Nữ 1.500m',key:'Luat_dien_kinh_nu_1500m_Bateco_2026',quick:[['Thành phần thi đấu','VĐV nữ có tên trong danh sách đăng ký của Liên minh.'],['Thể thức chính','03 vòng sân, khoảng 1.500m; tất cả VĐV chạy cùng một lượt, xuất phát đồng thời tại vị trí được bố trí.'],['Cách tính thắng / xếp hạng','Hoàn thành hợp lệ đủ 03 vòng và về đích trước xếp trên. Nhất, Nhì, Ba nhận HCV, HCB, HCĐ; tính vào tổng sắp Liên minh.']],notes:['Xuất phát đúng vị trí và sau hiệu lệnh Trọng tài.','Không cắt ngang sân, bỏ vòng, xô đẩy hoặc cản trở VĐV khác.','Không nhận hỗ trợ kéo, đẩy hoặc dìu chạy từ người khác.']},
 relay:{title:'Chạy tiếp sức',key:'Luat_chay_tiep_suc_Hoi_thao_Bateco_2026',quick:[['Thành phần thi đấu','Mỗi Liên minh 01 đội gồm 04 VĐV: 02 nam, 02 nữ.'],['Thể thức chính','Xuất phát đồng thời; mỗi VĐV chạy 01 vòng khoảng 500m, tổng mỗi đội khoảng 2.000m. Đăng ký thứ tự chạy trước thi đấu.'],['Cách tính thắng / xếp hạng','Đội hoàn thành hợp lệ với thời gian ngắn hơn xếp trên. Tính từ hiệu lệnh xuất phát đến khi VĐV lượt cuối về đích.']],notes:['Chỉ bắt đầu lượt chạy sau khi hoàn tất bàn giao tại khu vực quy định.','Không thay người hoặc đổi thứ tự đã đăng ký khi đang thi đấu.','Không rút ngắn cự ly, cản trở đối thủ hoặc nhận hỗ trợ kéo, đẩy, dìu chạy.']},
 pickle:{title:'Pickleball',key:'Luat_thi_dau_Pickleball_doi_nam_nu_Bateco_2026',quick:[['Thành phần thi đấu','Mỗi đội 01 nam, 01 nữ; không giới hạn số đội đăng ký vòng loại.'],['Thể thức chính','Vòng loại chia bảng; chọn 08 đội vào tứ kết, bán kết, chung kết loại trực tiếp. BO3: thắng 02 ván; mỗi ván 11 điểm, cách biệt 02 điểm.'],['Cách tính thắng / xếp hạng','Chỉ đội giao bóng ghi điểm. Vòng loại: thắng 01 điểm, thua 0; bằng điểm xét đối đầu → hiệu số ván → hiệu số điểm. Nếu vẫn bằng: BTC quyết định đấu bổ sung hoặc bốc thăm.']],notes:['Không thay người trong trận; thay đổi trước trận tiếp theo phải đăng ký.','Tuân thủ quy tắc hai lần nảy bóng trước khi đánh vô-lê.','Không vô-lê khi chạm kitchen hoặc vạch kitchen; đà sau vô-lê chạm kitchen cũng là lỗi.','Hai đội thua bán kết tranh HCĐ nếu thời gian cho phép.']},
 aoe:{title:'AOE',key:'Luat_thi_dau_AOE_4vs4_Random_Bateco_2026',quick:[['Thành phần thi đấu','Mỗi Liên minh 01 đội gồm 04 VĐV; không giới hạn dự bị, tất cả thuộc danh sách đăng ký.'],['Thể thức chính','AOE 1 – The Rise of Rome; 4vs4 Random, đời 3 không thành, không chòi; được lên đời 4. Vòng tròn một lượt, BO3: thắng 02 ván trước.'],['Cách tính thắng / xếp hạng','Thắng trận 01 điểm, thua 0. Bằng điểm xét hiệu số ván thắng − thua; vẫn bằng thì thi đấu bổ sung. Thắng ván khi toàn bộ đối phương bị đánh bại hoặc đội trưởng đối phương xác nhận đầu hàng.']],notes:['Trước click đời 3: không có quân; đã click nhưng chưa lên xong: tối đa 01 quân.','Chỉ chủ động đập dân sau khi lên xong đời 3; được dùng dân tự vệ khi bị đập. Người bơm tài nguyên phải đã click đời 3.','Cấm xây hoặc ken móng thành, chòi; một thành viên phạm lỗi xử thua trực tiếp khiến cả đội thua ván.','02 cảnh cáo trong cùng ván: xử thua ván. Không thay người khi ván đang diễn ra.']}
};
let selectedAthletics='men';
let ruleOverrides={};
const pairsToText=pairs=>pairs.map(p=>p.join(' | ')).join('\n');
const blocksToText=blocks=>blocks.map(b=>b.type==='table'?b.rows.map(r=>r.join(' | ')).join('\n')+'\n':b.text).join('\n');
function ruleDoc(key){const o=ruleOverrides[key];if(o)return o;const base=ruleSummaries[key];return base?{title:base.title,quick:base.quick,notes:base.notes,blocks:fullRules[base.key]}:null}
function ruleRawText(key){const o=ruleOverrides[key];if(o)return o.raw;const base=ruleSummaries[key];
 return base?{title:base.title,quick:pairsToText(base.quick),notes:base.notes.join('\n'),full:blocksToText(fullRules[base.key])}:{title:'',quick:'',notes:'',full:''}}
let scheduleOverride=null;
const scheduleRows=()=>scheduleOverride??schedule;
const scheduleRawText=()=>scheduleRows().map(r=>r.join(' | ')).join('\n');
function renderSchedule(){document.querySelector('#lich-trinh .timeline').innerHTML=scheduleRows().map(([t,n,tag])=>`<li><span class="timeline-dot"></span><time>${officialText(t)}</time><strong>${officialText(n)}</strong>${tag?`<span class="pill">${officialText(tag)}</span>`:''}</li>`).join('')}
async function loadSchedule(){try{const r=await fetch('/api/schedule',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)return;
  const d=await r.json();scheduleOverride=Array.isArray(d.schedule?.rows)&&d.schedule.rows.length?d.schedule.rows:null}catch{}}
async function refreshSchedule(){const before=JSON.stringify(scheduleOverride);await loadSchedule();if(JSON.stringify(scheduleOverride)!==before)renderSchedule()}
renderSchedule();
async function loadRules(){try{const r=await fetch('/api/rules',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)return;
  const d=await r.json();if(!Array.isArray(d.rules))return;const next={};for(const row of d.rules)next[row.key]=row;ruleOverrides=next}catch{}}
async function refreshRules(){const before=JSON.stringify(ruleOverrides);await loadRules();if(JSON.stringify(ruleOverrides)!==before)refreshRulesPanel()}
function refreshRulesPanel(){const active=document.querySelector('#luat-thi-dau [data-rules][aria-selected="true"]');renderSportPanel('rules',active?Number(active.dataset.rules):0)}
function fullRuleMarkup(blocks){let list=false;let out='';const close=()=>{if(list){out+='</ul>';list=false}};
 for(const block of blocks){if(block.type==='table'){close();out+='<div class="rule-reference-table">'+block.rows.map((row,i)=>i===0?`<div class="rule-table-head">${row.map(officialText).join(' / ')}</div>`:`<div class="rule-table-row"><strong>${officialText(row[0])}</strong><span>${officialText(row[1])}</span></div>`).join('')+'</div>'}else if(/^\d+[.\s]/.test(block.text)){close();out+=`<h4>${officialText(block.text)}</h4>`}else if(/^(LUẬT THI ĐẤU|HỘI THAO BATECO|ĐÔI NAM NỮ)/.test(block.text)){close();out+=`<p class="rule-original-title">${officialText(block.text)}</p>`}else{if(!list){out+='<ul>';list=true}out+=`<li>${officialText(block.text)}</li>`}}close();return out;
}
function renderOfficialRules(i){const panel=document.querySelector('#rules-panel');

 const key=i===0?'tug':i===1?selectedAthletics:i===2?'pickle':i===3?'aoe':'football',r=ruleDoc(key);
 if(!r){panel.innerHTML='<div class="rules-sheet"><h3>'+officialText(competitionViews[i].label)+'</h3><p>Đang cập nhật luật thi đấu</p></div>';return}
 const athletics=i===1?`<div class="athletics-choice" role="group" aria-label="Nội dung điền kinh">${['men','women','relay'].map(k=>`<button type="button" data-athletics="${k}" aria-pressed="${k===selectedAthletics}">${officialText(ruleDoc(k)?.title??'')}</button>`).join('')}</div>`:'';
 panel.innerHTML=athletics+`<article class="rules-sheet"><div class="rules-title"><span class="rules-icon" aria-hidden="true">${competitionViews[i].icon}</span><h3>${officialText(r.title)}</h3></div><dl class="rule-summary">${r.quick.map(([label,value])=>`<div><dt>${officialText(label)}</dt><dd>${officialText(value)}</dd></div>`).join('')}</dl><div class="rule-notes"><h4>Lưu ý quan trọng</h4><ul>${r.notes.map(t=>`<li>${officialText(t)}</li>`).join('')}</ul></div><details class="full-rule"><summary>XEM LUẬT CHI TIẾT<span aria-hidden="true">+</span></summary><div class="full-rule-content">${fullRuleMarkup(r.blocks)}</div></details></article>`;
 panel.querySelectorAll('[data-athletics]').forEach(b=>b.onclick=()=>{selectedAthletics=b.dataset.athletics;renderOfficialRules(1);panel.querySelector(`[data-athletics="${selectedAthletics}"]`).focus()});
}

let pickleData=null;
// Phiên admin, đặt lại sau mỗi lần kiểm /api/admin/session. Ẩn nút Xóa chỉ là UX:
// chốt thật nằm ở isAdmin() phía server trên mọi route ghi.
let adminSession=false;
const pickleGroups={A:[['Hoàng Nam','Huyền Trang','TP'],['Đăng Hiếu','Quang Huy','TP'],['Đức Anh','Thanh Ngà','BP'],['Văn Hưng','Thái Đan','CP'],['Chí Hoàn','Văn Hải','CP']],B:[['Minh Hiếu','Huy Tuân','CP'],['Văn Tùng','Thu Hường','CP'],['Minh Toàn','Khánh Linh','BP'],['Tuấn Lộc','Thị Lương','TP'],['Bích Phượng','Đăng Tiến','BP']]};
const pickleAlliances=['TP','BP','CP'];
const pickleRounds=[[['A',0,2],['A',1,3],['B',0,1],['B',2,3]],[['A',0,1],['A',2,4],['B',0,2],['B',1,4]],[['A',0,3],['A',1,4],['B',0,3],['B',2,4]],[['A',0,4],['A',2,3],['B',0,4],['B',1,3]],[['A',2,1],['A',3,4],['B',1,2],['B',3,4]]];
const pickleScoreCodes=pickleRounds.map((round,r)=>round.map((m,c)=>`R${r+1}C${c+1}`)).flat();
const pickleFinalLabels={SF1:'Bán kết 1',SF2:'Bán kết 2',GOLD:'Tranh Huy chương Vàng',BRONZE:'Tranh Huy chương Đồng'};
const pickleFinalSlots={SF1:['Nhất bảng A','Nhì bảng B'],SF2:['Nhất bảng B','Nhì bảng A'],GOLD:['Thắng bán kết 1','Thắng bán kết 2'],BRONZE:['Thua bán kết 1','Thua bán kết 2']};
const pickleFinalCodes=Object.keys(pickleFinalLabels);
const emptyPickle=()=>({pairs:Object.fromEntries(['A','B'].map(g=>[g,pickleGroups[g].map(()=>['','',''])])),scores:Object.fromEntries(pickleScoreCodes.map(c=>[c,''])),groups:{A:{first:null,second:null},B:{first:null,second:null}},finals:Object.fromEntries(pickleFinalCodes.map(c=>[c,{score:'',winner:null}]))});
const pickleState=()=>{const base=emptyPickle(),d=pickleData;
 if(!d||typeof d!=='object')return base;
 if(d.pairs&&typeof d.pairs==='object')for(const g of ['A','B']){const list=d.pairs[g];if(!Array.isArray(list))continue;
  list.slice(0,5).forEach((row,i)=>{if(!Array.isArray(row))return;
   for(const k of [0,1])if(typeof row[k]==='string')base.pairs[g][i][k]=row[k];
   if(pickleAlliances.includes(row[2]))base.pairs[g][i][2]=row[2]})}
 if(d.scores&&typeof d.scores==='object')for(const c of pickleScoreCodes)if(typeof d.scores[c]==='string')base.scores[c]=d.scores[c];
 if(d.groups&&typeof d.groups==='object')for(const g of ['A','B']){const row=d.groups[g];if(!row||typeof row!=='object')continue;
  for(const k of ['first','second'])if(Number.isInteger(row[k])&&row[k]>=0&&row[k]<=4)base.groups[g][k]=row[k]}
 if(d.finals&&typeof d.finals==='object')for(const c of pickleFinalCodes){const m=d.finals[c];if(!m||typeof m!=='object')continue;
  if(typeof m.score==='string')base.finals[c].score=m.score;
  if(m.winner===1||m.winner===2)base.finals[c].winner=m.winner}
 return base};
const picklePair=(d,g,i)=>{const base=pickleGroups[g][i],over=d.pairs[g][i];return [over[0]||base[0],over[1]||base[1],over[2]||base[2]]};
const pickleTeam=(d,g,i)=>{const p=picklePair(d,g,i);return p[0]+' + '+p[1]};
const pickleName=(d,g,i)=>i===null?'':pickleTeam(d,g,i);
const pickleSides=d=>{const seat=(g,k)=>pickleName(d,g,d.groups[g][k]);
 const pick=(code,a,b)=>{const w=d.finals[code].winner;return w===1?a:w===2?b:''};
 const drop=(code,a,b)=>{const w=d.finals[code].winner;return w===1?b:w===2?a:''};
 const sf1=[seat('A','first'),seat('B','second')],sf2=[seat('B','first'),seat('A','second')];
 return {SF1:sf1,SF2:sf2,GOLD:[pick('SF1',...sf1),pick('SF2',...sf2)],BRONZE:[drop('SF1',...sf1),drop('SF2',...sf2)]}};
const pickleMatchLabel=(d,code)=>{const r=+code[1]-1,c=+code[3]-1,[g,i,j]=pickleRounds[r][c];return `Lượt ${r+1} · Sân ${c+1}: ${pickleTeam(d,g,i)} vs ${pickleTeam(d,g,j)}`};
const pickleScoreHtml=(code,score,label,winner)=>(score||winner)?`<span class="pickle-score">${score?officialText(score):'—'}${adminSession?`<button type="button" class="bracket-del-match" data-del-match="${code}" aria-label="Xóa tỉ số ${officialText(label)}">×</button>`:''}</span>`:'';
const pickleGroupsHtml=d=>`<div class="pickle-groups">${['A','B'].map(g=>`<div class="pickle-group"><h4>Bảng ${g}</h4><ol>${pickleGroups[g].map((row,i)=>{const p=picklePair(d,g,i);return `<li class="pickle-seat"><span>${officialText(p[0]+' + '+p[1])}</span><em>${officialText(p[2])}</em></li>`}).join('')}</ol></div>`).join('')}</div>`;
const pickleMatchHtml=(d,code,g,i,j,court)=>`<div class="pickle-match"><span class="pickle-court">Sân ${court}</span><span class="pickle-vs">${officialText(pickleTeam(d,g,i))}<i>vs</i>${officialText(pickleTeam(d,g,j))}</span>${pickleScoreHtml(code,d.scores[code],pickleMatchLabel(d,code))}</div>`;
const pickleRoundsHtml=d=>`<div class="pickle-rounds">${pickleRounds.map((round,r)=>`<div class="pickle-round"><h4>Lượt ${r+1}</h4>${round.map(([g,i,j],c)=>pickleMatchHtml(d,`R${r+1}C${c+1}`,g,i,j,c+1)).join('')}</div>`).join('')}</div>`;
const pickleSlotHtml=(name,label,winner)=>`<div class="bracket-slot${winner?' is-winner':''}${name?'':' is-empty'}">${name?`<small>${officialText(label)}</small>${officialText(name)}`:officialText(label)}</div>`;
const picklePairHtml=(d,code,sides)=>{const m=d.finals[code],labels=pickleFinalSlots[code];
 return `<div class="pickle-final"><h4>${officialText(pickleFinalLabels[code])}</h4><div class="bracket-pair">${pickleSlotHtml(sides[0],labels[0],m.winner===1)}${pickleSlotHtml(sides[1],labels[1],m.winner===2)}${pickleScoreHtml(code,m.score,pickleFinalLabels[code],m.winner)}</div></div>`};
const pickleFinalsHtml=d=>{const sides=pickleSides(d);
 return `<div class="pickle-finals">${pickleFinalCodes.map(c=>picklePairHtml(d,c,sides[c])).join('')}</div>`};
const pickleHtml=()=>{const d=pickleState();
 return `<h4 class="pickle-head">Thành phần bảng</h4>${pickleGroupsHtml(d)}<h4 class="pickle-head">Lịch thi đấu vòng bảng</h4>${pickleRoundsHtml(d)}<h4 class="pickle-head">Vòng chung kết</h4>${pickleFinalsHtml(d)}`};
function syncDrawEntryButtons(){const a=document.querySelector('#bang-dau [data-draw][aria-selected="true"]'),pickle=!!a&&Number(a.dataset.draw)===2;
 for(const b of document.querySelectorAll('#bang-dau [data-entry]'))b.hidden=(b.dataset.entry==='bracket')!==pickle}
function renderSportPanel(prefix,i){
 const s=competitionViews[i],d=officialCompetitionData[i],panel=document.querySelector(`#${prefix}-panel`);
 document.querySelectorAll(`[data-${prefix}]`).forEach(b=>{const active=Number(b.dataset[prefix])===i;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});panel.setAttribute('aria-labelledby',`${prefix}-tab-${i}`);
 if(prefix==='draw'){panel.innerHTML=i===2?`<div class="bracket-sheet"><h3>Vòng bảng và chung kết</h3>${pickleHtml()}</div>`:`<div class="draw-sheet"><h3>${s.label}</h3><div class="draw-columns">${s.columns.map(c=>`<span>${c}</span>`).join('')}</div>${d.rows.length?`<div class="official-rows">${d.rows.map((row,ri)=>`<div class="official-row${adminSession?' has-admin':''}">${s.columns.map((label,k)=>`<div><small>${label}</small><span>${officialText(row[k])}</span></div>`).join('')}${adminSession?`<div class="row-actions"><button type="button" class="row-delete" data-del-draw="${ri}" data-del-sport="${i}">Xóa</button></div>`:''}</div>`).join('')}</div>`:`<p class="pending">Chưa có ${i===1?'danh sách nội dung, VĐV và lượt chạy':'bảng đấu và cặp đấu'} chính thức.</p>`}</div>`;syncDrawEntryButtons()}
 else renderOfficialRules(i);
}
for(const prefix of ['draw','rules']){renderSportPanel(prefix,0);document.querySelectorAll(`[data-${prefix}]`).forEach(b=>{b.onclick=()=>renderSportPanel(prefix,Number(b.dataset[prefix]));b.onkeydown=e=>{let i=Number(b.dataset[prefix]);if(e.key==='ArrowRight')i=(i+1)%5;else if(e.key==='ArrowLeft')i=(i+4)%5;else if(e.key==='Home')i=0;else if(e.key==='End')i=4;else return;e.preventDefault();renderSportPanel(prefix,i);document.querySelector(`#${prefix}-tab-${i}`).focus()}})}
document.querySelectorAll('[data-arena]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.arena);renderSportPanel('rules',i);document.querySelector('#luat-thi-dau').scrollIntoView({behavior:'smooth',block:'start'});document.querySelector(`#rules-tab-${i}`).focus({preventScroll:true})});
for(const [id,kind,label] of [['bang-dau','draw','Nhập bảng đấu'],['bang-dau','bracket','Nhập vòng bảng'],['huy-chuong','medal','Nhập huy chương'],['ket-qua','result','Nhập kết quả'],['luat-thi-dau','rules','Nhập luật thi đấu']])document.querySelector('#'+id+' .section-head').insertAdjacentHTML('beforeend',`<button type="button" class="entry-button" data-entry="${kind}">${label}</button>`);syncDrawEntryButtons();
const navLinks=[...mainNav.querySelectorAll('a')];
function updateActiveNav(){const boundary=document.querySelector('header').getBoundingClientRect().height+40;let active=null;for(const a of navLinks){if(document.querySelector(a.hash).getBoundingClientRect().top<=boundary)active=a}navLinks.forEach(a=>{if(a===active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}
window.addEventListener('scroll',updateActiveNav,{passive:true});window.addEventListener('resize',updateActiveNav);updateActiveNav();
loadRules().then(refreshRulesPanel);
loadSchedule().then(renderSchedule);
setInterval(()=>{if(!document.hidden){refreshRules();refreshSchedule()}},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshRules();refreshSchedule()}});
if(window.IntersectionObserver&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
 const revealer=new IntersectionObserver((entries,obs)=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('bt-shown');obs.unobserve(e.target)}},{rootMargin:'0px 0px -8% 0px'});
 for(const s of document.querySelectorAll('.section:not(#bang-dau):not(#ket-qua)')){s.classList.add('bt-reveal');revealer.observe(s)}}
if(window.IntersectionObserver&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
 const fxHero=document.querySelector('.hero'),fxCanvas=document.createElement('canvas');
 fxCanvas.className='hero-fx';fxCanvas.setAttribute('aria-hidden','true');fxHero.prepend(fxCanvas);
 const fxCtx=fxCanvas.getContext('2d'),fxColors=['#76d8d0','#ff985b','#ffffff','#ffc08a'],fxMax=70,fxPerBurst=16,fxDprCap=1.5;
 let fxW=0,fxH=0,fxRaf=0,fxResizeRaf=0,fxOnScreen=false,fxOff=false,fxNextBurst=0,fxSparks=[];
 const fxResize=()=>{const r=Math.min(window.devicePixelRatio||1,fxDprCap);fxW=fxHero.clientWidth;fxH=fxHero.clientHeight;fxCanvas.width=Math.round(fxW*r);fxCanvas.height=Math.round(fxH*r);fxCtx.setTransform(r,0,0,r,0,0)};
 const fxBurst=()=>{
  if(fxSparks.length+fxPerBurst>fxMax)return;
  const x=fxW*(.08+Math.random()*.6),y=fxH*(.10+Math.random()*.16),color=fxColors[(Math.random()*fxColors.length)|0],speed=2.6+Math.random()*2.2;
  for(let i=0;i<fxPerBurst;i++){const angle=i/fxPerBurst*6.2832+Math.random()*.22,v=speed*(.55+Math.random()*.45);
   fxSparks.push({x,y,vx:Math.cos(angle)*v,vy:Math.sin(angle)*v,life:1,fade:.009+Math.random()*.006,color})}};
 const fxFrame=now=>{
  fxRaf=requestAnimationFrame(fxFrame);
  if(now>=fxNextBurst){fxBurst();fxNextBurst=now+1500+Math.random()*900}
  fxCtx.clearRect(0,0,fxW,fxH);fxCtx.lineWidth=2.1;fxCtx.lineCap='round';
  for(let i=fxSparks.length-1;i>=0;i--){const s=fxSparks[i];
   s.x+=s.vx;s.y+=s.vy;s.vy+=.028;s.vx*=.987;s.vy*=.987;s.life-=s.fade;
   if(s.life<=0){fxSparks.splice(i,1);continue}
   fxCtx.globalAlpha=s.life;fxCtx.strokeStyle=s.color;
   fxCtx.beginPath();fxCtx.moveTo(s.x-s.vx*6,s.y-s.vy*6);fxCtx.lineTo(s.x,s.y);fxCtx.stroke()}
  fxCtx.globalAlpha=1};
 const fxStop=()=>{if(!fxRaf)return;cancelAnimationFrame(fxRaf);fxRaf=0;fxSparks=[];fxCtx.clearRect(0,0,fxW,fxH)};
 const fxSync=()=>{if(!fxOff&&fxOnScreen&&!document.hidden){if(!fxRaf){fxNextBurst=0;fxRaf=requestAnimationFrame(fxFrame)}}else fxStop()};
 fxResize();
 new IntersectionObserver(entries=>{fxOnScreen=entries[0].isIntersecting;fxSync()}).observe(fxHero);
 document.addEventListener('visibilitychange',fxSync);
 matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{if(e.matches){fxOff=true;fxSync();fxCanvas.remove()}});
 window.addEventListener('resize',()=>{if(fxResizeRaf)return;fxResizeRaf=requestAnimationFrame(()=>{fxResizeRaf=0;fxResize()})})}
